toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #181926;
  font-family: "Rajdhani, sans-serif";
}

>slateBg = #181926;
>faceTop = #93C5FD;
>faceLeft = #3B82F6;
>faceRight = #1D4ED8;
>wireEdge = #BFDBFE;

rect #isoCubeTop {
  at: center of canvas offset 0px -100px;
  size: 160px 160px;
  fill: >faceTop;
  rotation: 45deg;
}

rect #isoCubeLeft {
  at: center of canvas offset -56px 14px;
  size: 114px 160px;
  fill: >faceLeft;
}

rect #isoCubeRight {
  at: center of canvas offset 56px 14px;
  size: 114px 160px;
  fill: >faceRight;
}

text #renderHeadline {
  at: below #isoCubeLeft offset 120px;
  content: "ISOMETRIC VOXEL MESH";
  font-size: 26px;
  font-weight: 700;
  color: #FFFFFF;
}

text #coordTelemetry {
  at: below #renderHeadline offset 10px;
  content: "X: 128.00  •  Y: 256.40  •  Z: 512.00  •  FACETS: 1,024";
  font-size: 12px;
  font-weight: 600;
  color: >faceTop;
}
